<?php require_once __DIR__.'/../../app/layout.php';$a=require_admin();
function store_gallery_image(array $file): string {if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK)throw new RuntimeException('One or more files could not be uploaded.');if(($file['size']??0)>5*1024*1024)throw new RuntimeException('Each image must be 5 MB or smaller.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($allowed[$mime]))throw new RuntimeException('Only JPG, PNG and WEBP images are allowed.');$dir=dirname(__DIR__).'/uploads';if(!is_dir($dir))mkdir($dir,0750,true);$path=$dir.'/'.bin2hex(random_bytes(16)).'.'.$allowed[$mime];if(!move_uploaded_file($file['tmp_name'],$path))throw new RuntimeException('Unable to store an image.');return '/uploads/'.basename($path);}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$action=$_POST['action']??'save';if($action==='delete'&&$id){$pdo->prepare('DELETE FROM gallery_images WHERE id=?')->execute([$id]);audit($pdo,$a['id'],'gallery_image_deleted','gallery_image',$id);flash('Gallery photo removed.');}elseif($action==='bulk_upload'){try{$count=0;$base=max(0,(int)($_POST['sort_order']??0));$status=in_array($_POST['status']??'',['active','inactive','pending'],true)?$_POST['status']:'active';foreach($_FILES['images']['name']??[] as $i=>$name){if(($_FILES['images']['error'][$i]??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)continue;$file=['name'=>$name,'type'=>$_FILES['images']['type'][$i]??'','tmp_name'=>$_FILES['images']['tmp_name'][$i]??'','error'=>$_FILES['images']['error'][$i]??UPLOAD_ERR_NO_FILE,'size'=>$_FILES['images']['size'][$i]??0];$image=store_gallery_image($file);$title=trim(pathinfo((string)$name,PATHINFO_FILENAME));$pdo->prepare('INSERT INTO gallery_images (title,image_path,sort_order,status) VALUES (?,?,?,?)')->execute([mb_substr($title?:'Gallery photo',0,200),$image,$base+$count,$status]);audit($pdo,$a['id'],'gallery_image_created','gallery_image',(int)$pdo->lastInsertId());$count++;}flash($count?"{$count} gallery photo(s) uploaded.":'Choose a folder or image files first.','error');}catch(Throwable $e){flash($e->getMessage(),'error');}}else{try{$title=trim($_POST['title']??'');$status=$_POST['status']??'active';$order=max(0,(int)($_POST['sort_order']??0));$existing=null;if($id){$s=$pdo->prepare('SELECT * FROM gallery_images WHERE id=?');$s->execute([$id]);$existing=$s->fetch();}$image=!empty($_FILES['image']['tmp_name'])?store_gallery_image($_FILES['image']):($existing['image_path']??null);if($title===''||!$image)throw new RuntimeException('A title and photo are required.');if($id){$pdo->prepare('UPDATE gallery_images SET title=?,image_path=?,sort_order=?,status=? WHERE id=?')->execute([$title,$image,$order,$status,$id]);flash('Gallery photo updated.');}else{$pdo->prepare('INSERT INTO gallery_images (title,image_path,sort_order,status) VALUES (?,?,?,?)')->execute([$title,$image,$order,$status]);flash('Gallery photo added.');}}catch(Throwable $e){flash($e->getMessage(),'error');}}redirect('/admin/gallery.php');}
$edit=['id'=>'','title'=>'','image_path'=>'','sort_order'=>0,'status'=>'active'];if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM gallery_images WHERE id=?');$s->execute([(int)$_GET['edit']]);$edit=$s->fetch()?:$edit;}$rows=$pdo->query('SELECT * FROM gallery_images ORDER BY sort_order ASC,id DESC')->fetchAll();header_html('Manage photo gallery');?>
<style>.gallery-upload{max-width:680px}.gallery-upload form{padding:20px}.gallery-upload input,.gallery-upload select{margin-bottom:8px}.gallery-upload .upload-grid{display:grid;grid-template-columns:1fr 160px 140px;gap:12px;align-items:end}.gallery-upload .upload-grid label{margin:0}.gallery-upload small{display:block;color:#586579;margin:4px 0 16px}.gallery-edit{max-width:680px;margin-top:22px}.gallery-edit form{display:grid;grid-template-columns:1fr 1fr 120px;gap:10px;padding:18px}.gallery-edit label{margin:0}@media(max-width:700px){.gallery-upload .upload-grid,.gallery-edit form{grid-template-columns:1fr}}</style><h1>Manage photo gallery</h1><p>Add a complete photo folder in one upload. Names of image files become their gallery titles automatically.</p><section class="gallery-upload"><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="upload-grid"><label>Choose photo folder<input type="file" name="images[]" accept="image/jpeg,image/png,image/webp" multiple webkitdirectory directory required></label><label>Starting order<input type="number" min="0" name="sort_order" value="0"></label><label>Status<select name="status"><option value="active">Visible</option><option value="pending">Pending</option><option value="inactive">Hidden</option></select></label></div><small>Chrome/Edge: choose a folder. Other browsers: select multiple photos. JPG, PNG or WEBP, maximum 5 MB each.</small><button name="action" value="bulk_upload">Upload selected photos</button></form></section>
<?php if($edit['id']):?><section class="gallery-edit"><h2>Edit photo</h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=e((string)$edit['id'])?>"><label>Title<input name="title" value="<?=e($edit['title'])?>" required></label><label>Replace photo<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><label>Order<input type="number" name="sort_order" value="<?=e((string)$edit['sort_order'])?>"></label><label>Status<select name="status"><option value="active" <?=$edit['status']==='active'?'selected':''?>>Visible</option><option value="inactive" <?=$edit['status']==='inactive'?'selected':''?>>Hidden</option></select></label><button>Update</button></form></section><?php endif;?><h2>Gallery photos</h2><table><tr><th>Photo</th><th>Title</th><th>Order</th><th>Status</th><th></th></tr><?php foreach($rows as $row):?><tr><td><img src="<?=e($row['image_path'])?>" alt="" width="90" height="55" style="object-fit:cover"></td><td><?=e($row['title'])?></td><td><?=e((string)$row['sort_order'])?></td><td><?=e($row['status'])?></td><td><a href="?edit=<?=$row['id']?>">Edit</a> <form method="post" style="display:inline"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$row['id']?>"><button name="action" value="delete">Delete</button></form></td></tr><?php endforeach;?></table><?php footer_html();
